def perevod(n):
    if n == 0:
        return '0'
    s = ''
    while n != 0:
        s = str(n % 5) + s
        n //= 5
    return s
def f(n):
    s = perevod(n)
    if n % 2 == 0:
        s = s + perevod(int(s[-1],5) * 3)
    else:
        if len(s) == 1:
            s = s
        else:
            s = s[-1] + s[1:-1] + s[0]
        s += '1'
    return perevod(int(s,5)) #избавляемся от незначащих нулей

for i in range(1,10000):
    if f(i).count('0') == 4:
        print(i)
        break
